-- Generado por database/importar_ecocrop.py -- NO editar a mano, regenerar desde el CSV.
-- Ver advertencia completa en el encabezado de ese script: opinion experta, no medicion.
-- Idempotente: actualiza las filas de EcoCrop existentes e inserta las que falten.

BEGIN;

CREATE TEMP TABLE _ecocrop (
  especie VARCHAR PRIMARY KEY,
  nombre_cientifico VARCHAR,
  nombres_comunes TEXT,
  familia_botanica VARCHAR,
  forma_vida VARCHAR,
  categorias TEXT[],
  ph_suelo_min FLOAT,
  ph_opt_min FLOAT,
  ph_opt_max FLOAT,
  ph_suelo_max FLOAT,
  tb FLOAT,
  t_opt_min FLOAT,
  t_optima FLOAT,
  t_opt_max FLOAT,
  tc FLOAT,
  temperatura_letal FLOAT,
  lluvia_anual_min FLOAT,
  lluvia_anual_opt_min FLOAT,
  lluvia_anual_opt_max FLOAT,
  lluvia_anual_max FLOAT,
  luz_min VARCHAR,
  luz_opt_min VARCHAR,
  luz_opt_max VARCHAR,
  luz_max VARCHAR,
  fotoperiodo VARCHAR,
  ciclo_min_dias INT,
  ciclo_max_dias INT
) ON COMMIT DROP;


UPDATE requisitos_especie r SET ph_suelo_min = e.ph_suelo_min, ph_opt_min = e.ph_opt_min, ph_opt_max = e.ph_opt_max, ph_suelo_max = e.ph_suelo_max, tb = e.tb, t_opt_min = e.t_opt_min, t_optima = e.t_optima, t_opt_max = e.t_opt_max, tc = e.tc, temperatura_letal = e.temperatura_letal, lluvia_anual_min = e.lluvia_anual_min, lluvia_anual_opt_min = e.lluvia_anual_opt_min, lluvia_anual_opt_max = e.lluvia_anual_opt_max, lluvia_anual_max = e.lluvia_anual_max, luz_min = e.luz_min, luz_opt_min = e.luz_opt_min, luz_opt_max = e.luz_opt_max, luz_max = e.luz_max, fotoperiodo = e.fotoperiodo, ciclo_min_dias = e.ciclo_min_dias, ciclo_max_dias = e.ciclo_max_dias
FROM _ecocrop e
WHERE r.especie = e.especie AND r.variedad_local IS NULL AND r.fuente = 'FAO_EcoCrop_opinion_experta';

SELECT e.especie, NULL, e.ph_suelo_min, e.ph_opt_min, e.ph_opt_max, e.ph_suelo_max, e.tb, e.t_opt_min, e.t_optima, e.t_opt_max, e.tc, e.temperatura_letal, e.lluvia_anual_min, e.lluvia_anual_opt_min, e.lluvia_anual_opt_max, e.lluvia_anual_max, e.luz_min, e.luz_opt_min, e.luz_opt_max, e.luz_max, e.fotoperiodo, e.ciclo_min_dias, e.ciclo_max_dias, 'FAO_EcoCrop_opinion_experta'
FROM _ecocrop e
WHERE NOT EXISTS (SELECT 1 FROM requisitos_especie r
                  WHERE r.especie = e.especie AND r.variedad_local IS NULL);

SELECT especie, nombre_cientifico, nombres_comunes, familia_botanica, forma_vida, categorias, 'FAO_EcoCrop_opinion_experta'
FROM _ecocrop
ON CONFLICT (especie) DO UPDATE SET nombre_cientifico = EXCLUDED.nombre_cientifico,
  nombres_comunes = EXCLUDED.nombres_comunes, familia_botanica = EXCLUDED.familia_botanica,
  forma_vida = EXCLUDED.forma_vida, categorias = EXCLUDED.categorias, fuente = EXCLUDED.fuente;

SELECT e.especie, NULL, '*', 'helada', e.temperatura_letal, 1, 'total', 0, 'FAO_EcoCrop_opinion_experta'
FROM _ecocrop e
WHERE e.temperatura_letal < 0
  AND NOT EXISTS (SELECT 1 FROM regla_dano_especie d
                  WHERE d.especie = e.especie AND d.peligro = 'helada' AND d.fuente = 'FAO_EcoCrop_opinion_experta');

COMMIT;
